-- Vídeos guiados do Protocolo Postura Livre nos exercícios do Dr. Pablo (2026-11-24).
-- Arquivos em public/videos-exercicios/ (vídeo .mp4 e capa .webp). Aplicado no banco de produção.

update public.exercicios set video_path = 'videos-exercicios/retracao-cervical.mp4', instrucoes = 'Sente-se alto, olhando para a frente. Leve o queixo para trás, sem abaixar a cabeça, como o pescoço do pombo: para a frente e para trás. Movimentos lentos e contínuos. Cuidado: o segredo está no queixo; não incline a cabeça para baixo.', series_padrao = 1, reps_padrao = '12', ativo = true where nome = 'Retração cervical (queixo para trás)';
update public.exercicios set video_path = 'videos-exercicios/postura-da-crianca.mp4', instrucoes = 'Comece em quatro apoios, como no gato e camelo. Leve o bumbum em direção aos calcanhares e as mãos um pouco mais à frente para alongar as costas. Respire devagar e volte. Cuidado: se incomodar os joelhos, coloque um travesseiro entre o quadril e os calcanhares.', series_padrao = 2, reps_padrao = '30 s', ativo = true where nome = 'Postura da criança';
update public.exercicios set video_path = 'videos-exercicios/rotacao-toracica.mp4', instrucoes = 'Em quatro apoios, coloque uma mão na nuca. O cotovelo desce por dentro, em direção ao braço de apoio, e depois sobe abrindo para o teto, com o olhar acompanhando. Cuidado: quadril parado; o giro vem do tronco.', series_padrao = 2, reps_padrao = '8 por lado', ativo = true where nome = 'Rotação torácica em quatro apoios';
update public.exercicios set nome = 'Braços à frente de bruços', video_path = 'videos-exercicios/bracos-a-frente-de-brucos.mp4', instrucoes = 'Deite de bruços com a testa perto do chão, o corpo alinhado e os cotovelos dobrados à frente. Aproxime as escápulas ao subir os braços e segure 3 segundos. Cuidado: pescoço longo; não levante a cabeça.', series_padrao = 1, reps_padrao = '12 (segure 3 s)', ativo = true where nome = 'W deitado de bruços';
update public.exercicios set nome = 'Flexor do quadril (semiajoelhado)', video_path = 'videos-exercicios/flexor-do-quadril.mp4', instrucoes = 'Fique semiajoelhado, com um joelho no chão (sobre uma toalha). Leve o quadril à frente e volte, devagar; se quiser, leve os braços à frente ou para cima. Cuidado: contraia o bumbum e não arqueie a lombar.', series_padrao = 1, reps_padrao = '12 por lado', ativo = true where nome = 'Alongamento do iliopsoas ajoelhado';
update public.exercicios set video_path = 'videos-exercicios/passar-a-agulha.mp4', instrucoes = 'Em quatro apoios, como na rotação torácica. Leve a mão para o teto, acompanhando com o olhar, e depois passe essa mão por baixo do outro braço, girando a parte alta das costas. Cuidado: amplie o movimento aos poucos, sem dor.', series_padrao = 2, reps_padrao = '8 por lado', ativo = true where nome = 'Passar a agulha';
update public.exercicios set nome = 'Extensão de costas (cobra)', video_path = 'videos-exercicios/cobra.mp4', instrucoes = 'Deite de bruços com a testa perto do chão e o pescoço alinhado. Suba o peito e os braços juntos, levando as mãos para trás, e segure 3 segundos. Cuidado: olhe para o chão, sem jogar a cabeça para trás.', series_padrao = 1, reps_padrao = '12 (segure 3 s)', ativo = true where nome = 'Cobra de bruços';
update public.exercicios set video_path = 'videos-exercicios/perdigueiro.mp4', instrucoes = 'Em quatro apoios, suba juntos o braço e a perna opostos até a linha do tronco. Segure 3 segundos respirando e volte devagar. Cuidado: devagar e sem desequilibrar; é comum um lado ser mais difícil que o outro.', series_padrao = 3, reps_padrao = '8 de cada lado', ativo = true where nome = 'Perdigueiro';
update public.exercicios set video_path = 'videos-exercicios/ponte.mp4', instrucoes = 'Deite de barriga para cima, joelhos dobrados e pés apoiados. Suba o quadril até formar uma linha entre joelho, quadril e ombro, usando o bumbum, e desça devagar. Cuidado: use o bumbum, sem arquear a lombar.', series_padrao = 3, reps_padrao = '12', ativo = true where nome = 'Ponte de glúteo';
update public.exercicios set video_path = 'videos-exercicios/gato-camelo.mp4', instrucoes = 'Em quatro apoios, mãos abaixo dos ombros e joelhos abaixo do quadril. Arredonde as costas olhando para o umbigo e depois afunde as costas olhando para a frente, mobilizando a coluna inteira. Cuidado: tudo lento e contínuo.', series_padrao = 2, reps_padrao = '10', ativo = true where nome = 'Gato e camelo';
update public.exercicios set video_path = 'videos-exercicios/livro-aberto.mp4', instrucoes = 'Deite de barriga para cima com os joelhos dobrados. Deixe os joelhos tombarem juntos para um lado e abra os braços para o outro, com a cabeça acompanhando; solte o ar enquanto abre. Volte e troque o lado. Cuidado: movimento sem dor; o alongamento é no peito e no meio das costas.', series_padrao = 2, reps_padrao = '8 por lado', ativo = true where nome = 'Abertura de livro';
update public.exercicios set video_path = 'videos-exercicios/peitoral-na-porta.mp4', instrucoes = 'Apoie a mão e o braço no batente da porta. Leve o corpo à frente até sentir o peito alongar e segure. Cuidado: sem arquear a lombar e sem subir o ombro.', series_padrao = 2, reps_padrao = '20 s por lado', ativo = true where nome = 'Alongamento de peitoral na porta';

-- Quem tinha "Y e T deitado de bruços" passa a ter "Braços à frente de bruços" (mesma musculatura, agora com vídeo).
update public.paciente_exercicios pe set exercicio_id = (select id from public.exercicios where nome = 'Braços à frente de bruços'), reps = '12 (segure 3 s)'
  where pe.exercicio_id = (select id from public.exercicios where nome = 'Y e T deitado de bruços')
    and not exists (select 1 from public.paciente_exercicios x where x.paciente_id = pe.paciente_id and x.exercicio_id = (select id from public.exercicios where nome = 'Braços à frente de bruços'));
delete from public.paciente_exercicios where exercicio_id = (select id from public.exercicios where nome = 'Y e T deitado de bruços')
  and paciente_id in (select paciente_id from public.paciente_exercicios where exercicio_id = (select id from public.exercicios where nome = 'Braços à frente de bruços'));
